const TH15_STAR_R: int = 608;       // source etSprite type=16 -> TH15 type 16 row base

// Source EX record 1 (:2352): ACCEL type 4, a=240, r=0.005..0.015, s=pi/2.
// Entering direction is fixed down; clear the Cartesian acceleration after 240 frames.
xformdef MOON_ACCEL(g: fx) {
    @240 set_gravity(0fx, g);
    stop_fx();
}

// Source :2312-2336 BossCard7_Moon.  anmSelect/anmSetSprite/anmScale/anmScaleTime,
// unknown544/549, playSound are omitted as presentation/unknown (see report.md).
async sub moon_main(inherited_f0: fx) {
    set_self_fx(0, inherited_f0);           // source :2275 parent F0=1.3 handed to child
    set_hurtbox(54fx);                      // source setHurtbox(108,108) -> radius 54
    set_hitbox(48fx);                       // source setHitbox(96,96) -> radius 48
    set_invuln(10000);                      // source :2324
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // source moveVel(ANGLE_PLAYER, 0)
    move_speed(120, 3fx, EASE_LINEAR);      // source moveSpeedTime(120, 0, 3.0)
    spawn moon_track();                     // source @BossTrase() async
    set_self_fx(0, 64fx);                   // source :2329 %F0=64.0
    loop { wait(1000); }                    // source :2331-2334
}

// Source :2827-2846 BossTrase.  Bounds are the source FINAL_X/Y screen window.
async sub moon_track() {
    loop {
        if $self_x < -192fx || $self_x > 192fx || $self_y > 448fx || $self_y < 0fx {
            move_vel(0, aim_player(), 0fx, EASE_LINEAR);     // :2832-2833
            move_speed(1, 0fx, EASE_LINEAR);
            spawn moon_wall();                               // :2836 async
            wait(30);                                        // :2837
            var u: fx = (rand(65536) - 32768) as fx / 32768;
            var off: int = (u * 1820fx) as int;              // RANDF2*0.17453292 rad ~ +/-10 deg
            move_vel(0, aim_player() + off as angle, 0fx, EASE_LINEAR); // :2838
            move_speed(120, 8fx, EASE_LINEAR);               // :2839
            wait(30);                                        // :2840
        }
        wait(1);                                             // :2842
    }
}

// Source :2338-2362 BossCard7_Moon_at.  Each of the 12 source iterations configures
// EX record 1 (one ACCEL r shared by the pair) and emits two absolute-offset bullets:
// x = +A/+rand*8 and -A/+rand*8 at y=0, A=0,16,...,176, then waits 1 frame.
async sub moon_wall() {
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, 6);           // source etSprite(0,16,6)
    sh_aim(0, 0);                           // source etAim(0,1): fixed-direction fan
    sh_ring(0, 0);                          // fan, not ring
    sh_count(0, 1, 1);                      // source etCount(0,1,1)
    sh_angle(0, 90deg, 0deg);               // source etAngle(0, pi/2, 0.17453292)
    sh_speed(0, 1fx, 0fx);                  // source etSpeed(0,1,1), one layer
    var a: fx = 0fx;                        // source %A = _f(0)
    for i in 0..12 {                        // source $B=12
        var u1: fx = (rand(65536) - 32768) as fx / 32768;
        var g: fx = 0.01fx + u1 * 0.005fx;  // source :2352 r = 0.01 + RANDF2*0.005
        sh_xform(0, MOON_ACCEL(g));
        var u2: fx = (rand(65536) - 32768) as fx / 32768;
        sh_offset_abs(0, a + u2 * 8fx, 0fx);    // source :2353
        sh_fire(0);                             // source :2354
        var u3: fx = (rand(65536) - 32768) as fx / 32768;
        sh_offset_abs(0, -a + u3 * 8fx, 0fx);   // source :2355
        sh_fire(0);                             // source :2356
        a = a + 16fx;                           // source :2357
        wait(1);                                // source :2358
    }
}

// moveRand(30, 4, 2.0): verified TH16/TH18 412 sample from movement.md, reused here
// with this card's limit (0,128,240,64) => x in [-120,120], y in [96,160].  The
// speed slope is linear 2.0*(1-k/30); mode 4 does not change the speed channel.
sub boss_move_rand(dur: int, speed0: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -25fx {
        a = r / 3;
    } else if $self_x > 25fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    var ux: fx = cos(a as angle);
    var uy: fx = sin(a as angle);
    for k in 1..(dur + 1) {
        var sp: fx = speed0 * (dur - k) / dur;
        var nx: fx = $self_x + ux * sp;
        var ny: fx = $self_y + uy * sp;
        if nx < -120fx { nx = -120fx; }
        if nx > 120fx { nx = 120fx; }
        if ny < 96fx { ny = 96fx; }
        if ny > 160fx { ny = 160fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
        wait(1);
    }
}

// Source :2235-2310 BossCard7 on the real Boss7 carrier.
async sub source_boss() {
    set_invuln(65535);                      // independent no-DPS training shell
    set_hurtbox(20fx);                      // source Boss :31 setHurtbox(40,40)
    set_hitbox(24fx);                       // source Boss :32 setHitbox(48,48)
    // Entry position (0,128) and moveLimit(0,128,240,64) come from the task context;
    // the fresh carrier starts there with zero velocity.  setChapter/unknown569,
    // etCancel/etClear, killAllAsync/enmKillAll, spellEnd/funcSet/laserCancel and the
    // sound/counter/UI lines are omitted per the approved shell/section policy.
    wait(4);                                // source :2244-2248, timerReset at t=4
    wait(90);                               // source :2273 +90 => t=94
    _ = spawn_enemy($self_x, $self_y, 1000, 0, 0, 0, moon_main(1.3fx)); // :2275-2276
    var c: int = 2;                         // source $C=2 (:2278)
    while c != 0 {
        c = c - 1;                          // source :2295 if ($C--)
        var d: int = 3;                     // source :2281
        while d != 0 {
            d = d - 1;                      // source :2288 if ($D--)
            wait(90);                       // source :2284
            boss_move_rand(30, 2fx);    // source :2285 moveRand(30,4,2.0)
            wait(10);                       // source :2286 wait(40), 30 consumed by motion
        }
        // anmPlay(1,75), playSound(54) omitted as presentation
        wait(120);                          // source :2291
        _ = spawn_enemy($self_x, $self_y, 1000, 0, 0, 0, moon_main(1.3fx)); // :2292
        wait(120);                          // source :2293
    }
    var e: int = 100000;                    // source $E=100000 (:2296)
    while e != 0 {
        e = e - 1;                          // source :2303 if ($E--)
        wait(90);                           // source :2299
        boss_move_rand(30, 2fx);        // source :2300
        wait(10);                           // source :2301 wait(40), 30 consumed by motion
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, source_boss); // inherited HP path 3000
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_CARD7, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
